package practice;

import java.util.Arrays;
import java.util.List;

/** A page sent to the engineers on call. */
public final class Alert {
    private final String title;
    private final List<String> recipients;

    private Alert(String title, List<String> recipients) {
        this.title = title;
        this.recipients = recipients;
    }

    /**
     * An alert with this title for these recipients. The pager shows the recipients in
     * alphabetical order, and an alert keeps the recipients it was created with.
     */
    public static Alert to(String title, String... recipients) {
        if (recipients == null) {
            return new Alert(title, List.of());
        }
        String[] sorted = recipients.clone();
        Arrays.sort(sorted);
        return new Alert(title, List.of(sorted));
    }

    public String title() {
        return title;
    }

    /** The recipients, in alphabetical order. */
    public List<String> recipients() {
        return recipients;
    }

    /** The line the pager shows. */
    public String render() {
        return title + " -> " + String.join(", ", recipients());
    }
}

package practice;

import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            String[] rotation = {"vik", "ada", "luz"};
            Alert lastWeek = Alert.to("CPU over 90% on api-3", rotation);
            rotation[0] = "noor";
            rotation[1] = "fen";
            rotation[2] = "bea";
            System.out.println("last week's alert: " + lastWeek.render());
            System.out.println("this week's alert: " + Alert.to("Replica lag 40 s", rotation).render());
            System.out.println("rotation after sending: " + Arrays.toString(rotation));
            String[] notSetUp = null;
            System.out.println("fresh install: " + Alert.to("Disk 95% full", notSetUp).render());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

